// Per k step: broadcast a[kk] (Y15) and fused multiply-add one 16-wide row of
// each panel into its two accumulators. The main loop takes 2 k steps.
TEXT ·gemv1AVX2I(SB), NOSPLIT, $0-40
	MOVQ a+0(FP), DI
	MOVQ b+8(FP), SI
	MOVQ panelStride+16(FP), R8
	MOVQ k+24(FP), CX
	MOVQ out+32(FP), DX


	VXORPS Y0, Y0, Y0
	VXORPS Y1, Y1, Y1

	MOVQ  CX, BX
	SHRQ  $1, BX
	ANDQ  $1, CX
	TESTQ BX, BX
	JZ    tail

loop2:
	VBROADCASTSS 0(DI), Y15
	VPMOVSXBD 0(SI), Y8
	VCVTDQ2PS Y8, Y8
	VPMOVSXBD 8(SI), Y9
	VCVTDQ2PS Y9, Y9
	VFMADD231PS Y8, Y15, Y0
	VFMADD231PS Y9, Y15, Y1
	VBROADCASTSS 4(DI), Y15
	VPMOVSXBD 16(SI), Y8
	VCVTDQ2PS Y8, Y8
	VPMOVSXBD 24(SI), Y9
	VCVTDQ2PS Y9, Y9
	VFMADD231PS Y8, Y15, Y0
	VFMADD231PS Y9, Y15, Y1
	ADDQ $32, SI
	ADDQ $8, DI
	DECQ BX
	JNZ  loop2

tail:
	TESTQ CX, CX
	JZ    done
	VBROADCASTSS 0(DI), Y15
	VPMOVSXBD 0(SI), Y8
	VCVTDQ2PS Y8, Y8
	VPMOVSXBD 8(SI), Y9
	VCVTDQ2PS Y9, Y9
	VFMADD231PS Y8, Y15, Y0
	VFMADD231PS Y9, Y15, Y1

done:
	VMOVUPS Y0, 0(DX)
	VMOVUPS Y1, 32(DX)
	VZEROUPPER
	RET
